function renderStudentProgress(data,notice=''){
 let start=progressStartAt(),attempts=(data.attempts||[]).filter(x=>Number(x.startedAt)>start),completed=attempts.filter(x=>x.status==='completed'),answered=completed.reduce((n,x)=>n+Number(x.correctAnswers)+Number(x.wrongAnswers),0),correct=completed.reduce((n,x)=>n+Number(x.correctAnswers),0),points=correct*100,pct=answered?Math.round(correct/answered*100):0,grade=String(data.student?.grade||S.student.grade),games=G[grade]?.games||[],byGame=games.map(game=>{let all=attempts.filter(x=>x.game===game),done=all.filter(x=>x.status==='completed'),a=done.reduce((n,x)=>n+Number(x.correctAnswers)+Number(x.wrongAnswers),0),c=done.reduce((n,x)=>n+Number(x.correctAnswers),0);return{game,attempts:all.length,completed:done.length,pct:a?Math.round(c/a*100):0}}),weakest=byGame.find(x=>x.completed===0)||[...byGame].filter(x=>x.completed).sort((a,b)=>a.pct-b.pct)[0],badges=[['✦','Primeira missão','Conclua seu primeiro jogo',completed.length>=1],['🔎','Olhar atento','Acerte pelo menos 3 questões',correct>=3],['⚡','Sequência','Alcance 500 pontos',points>=500],['◆','Guardião da língua','Conclua todos os jogos da etapa',games.length>0&&byGame.every(x=>x.completed>0)]];
 let reportQuery=`studentId=${encodeURIComponent(S.student.id)}&startAt=${encodeURIComponent(start)}`;
 let content=document.querySelector('#student-progress-content');content.className='';content.innerHTML=`${notice?`<div class="reset-success" role="status">${escapeHtml(notice)}</div>`:''}<div class="student-progress-hero"><div><span class="eyebrow">CADERNO DE HABILIDADES</span><h2>Seu caminho até aqui</h2><p>O progresso de <b>${escapeHtml(data.student?.name||S.student.name)}</b>, turma <b>${escapeHtml(data.student?.className||S.student.className)}</b>, considera as missões concluídas. Errar também faz parte da trilha: use as explicações para tentar de novo.</p></div><div class="mastery-ring" style="--pct:${pct}%"><strong>${pct}%</strong><span>domínio geral</span></div></div><div class="journey-stats"><div><span>Questões respondidas</span><strong>${answered}</strong></div><div><span>Acertos</span><strong>${correct}</strong></div><div><span>Pontos</span><strong>${points}</strong></div></div><div class="learning-recommendation"><div><b>${weakest?'Recomendação personalizada':'Primeiro passo sugerido'}${weakest?`: ${escapeHtml(weakest.game)}`:''}</b><p>${weakest?.completed?'Esta missão apresenta a maior oportunidade de avanço.':'Comece praticando uma missão para formar seu mapa de aprendizagem.'}</p></div>${weakest?`<button class="btn alt" data-review-game="${escapeHtml(weakest.game)}">Praticar agora</button>`:''}</div><section class="skills-panel"><span class="eyebrow">POR MISSÃO</span><h2>Mapa de aprendizagem — ${escapeHtml(G[grade]?.name||grade)}</h2><div class="student-game-map">${byGame.map(x=>`<div class="student-progress-row"><div><b>${escapeHtml(x.game)}</b><small>${x.attempts} tentativa(s) • ${x.completed} concluída(s)</small></div><div class="learning-bar" aria-label="${x.pct}% de acertos"><span style="width:${x.pct}%"></span></div><strong>${x.pct}%</strong></div>`).join('')}</div></section><section class="achievement-panel"><span class="eyebrow">CONQUISTAS</span><h2>Marcos da jornada</h2><div class="achievement-grid">${badges.map(x=>`<div class="achievement ${x[3]?'':'locked'}"><span>${x[0]}</span><div><b>${x[1]}</b><small>${x[3]?'Conquistada':x[2]}</small></div></div>`).join('')}</div></section><div class="student-progress-actions no-print"><a class="btn" href="/api/progress/student-pdf?${reportQuery}" target="_blank" rel="noopener">Abrir resultado em PDF ↗</a><a class="btn alt" href="/api/progress/student-print?${reportQuery}" target="_blank" rel="noopener">Abrir versão para impressão ↗</a><button class="danger-text" type="button" id="reset-student-progress">Recomeçar meu progresso</button></div><p class="pdf-download-note no-print">O documento abrirá em uma nova aba. Na versão para impressão, use o botão “Imprimir ou salvar em PDF”.</p><div class="reset-confirmation no-print" id="reset-progress-confirmation" hidden><p><b>Deseja realmente recomeçar?</b><br>O painel do estudante voltará a zero, mas o histórico anterior continuará disponível para o professor.</p><div class="actions"><button class="btn" type="button" id="confirm-reset-progress">Sim, recomeçar</button><button class="btn alt" type="button" id="cancel-reset-progress">Cancelar</button></div></div>`;
 let practice=document.querySelector('[data-review-game]');if(practice)practice.onclick=()=>start(practice.dataset.reviewGame);
 bindProgressReset(data,grade);
}
function teacher(){out(`<div class="pagehead"><span class="eyebrow">Área do professor</span><h1>Plano de mediação pedagógica</h1><p class="lead">Orientações para planejar a aplicação do percurso e acompanhar a aprendizagem.</p></div><section class="section"><div class="teacher-actions no-print"><button class="btn" data-page="report">📊 Abrir painel de progresso</button></div><div class="tabs">${['6','9','3'].map(k=>`<button data-t="${k}" class="${k===S.grade?'active':''}">${G[k].name}</button>`).join('')}</div>${teach(S.grade)}</section>`);document.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{S.grade=b.dataset.t;teacher()});document.querySelectorAll('.accordion>button').forEach(b=>b.onclick=()=>b.parentElement.classList.toggle('open'))};
async function teacherLogin(event){event.preventDefault();let status=document.querySelector('#teacher-login-status'),password=document.querySelector('#teacher-password').value;status.textContent='Verificando…';let response=await fetch('/api/teacher/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password})}),data=await response.json();if(!response.ok){status.textContent=data.error||'Não foi possível entrar.';return}teacherProgress()}
