async function teacherProgress(){out(`<div class="pagehead"><span class="eyebrow">Área do professor</span><h1>Progresso dos estudantes</h1><p class="lead">Acompanhe jogos iniciados e concluídos, tentativas, acertos e erros.</p></div><section class="section" id="report-area"><div class="print-only"><h1>Relatório de progresso — Das trevas para a luz</h1><p id="print-date"></p></div><div id="report-content" class="emptyreport">Carregando dados…</div></section>`);try{let r=await fetch('/api/teacher/report'),d=await r.json();if(r.status===401){document.querySelector('#report-content').innerHTML=`<div class="teacher-login"><h2>Entrada do professor</h2><p>Digite a senha administrativa definida na Cloudflare para consultar os resultados das turmas.</p><form id="teacher-login-form"><label>Senha do professor<input id="teacher-password" type="password" required autocomplete="current-password"></label><button class="btn" type="submit">Entrar</button><p id="teacher-login-status" role="status"></p></form></div>`;document.querySelector('#teacher-login-form').onsubmit=teacherLogin;document.querySelector('#teacher-password').focus();return}if(!r.ok)throw new Error(d.error||'Não foi possível abrir o painel.');renderReport(d);let toolbar=document.querySelector('.report-toolbar');if(toolbar){let logout=document.createElement('button');logout.className='danger-text';logout.type='button';logout.textContent='Sair do painel';logout.onclick=teacherLogout;toolbar.appendChild(logout)}}catch(e){document.querySelector('#report-content').innerHTML=`<h2>Painel indisponível</h2><p>${escapeHtml(e.message)}</p>`}};
function renderReport(data){let attempts=data.attempts||[],answers=data.answers||[];let classes=[...new Set(attempts.map(x=>x.className))],games=[...new Set(attempts.map(x=>x.game))];document.querySelector('#print-date').textContent=`Gerado em ${new Date(data.generatedAt).toLocaleString('pt-BR')}`;document.querySelector('#report-content').className='';document.querySelector('#report-content').innerHTML=`<div class="report-toolbar no-print"><div class="reportfilters"><label>Turma<select id="filter-class"><option value="">Todas</option>${classes.map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select></label><label>Jogo<select id="filter-game"><option value="">Todos</option>${games.map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select></label><label>Situação<select id="filter-status"><option value="">Todas</option><option value="completed">Concluídos</option><option value="started">Iniciados</option></select></label></div><div class="report-export-actions"><a class="btn" id="teacher-report-pdf-link" href="/api/teacher/report-pdf" target="_blank" rel="noopener">Abrir PDF ↗</a><a class="btn alt" id="teacher-report-print-link" href="/api/teacher/report-print" target="_blank" rel="noopener">Versão para impressão ↗</a><p class="pdf-download-note">Os documentos abrem em nova aba e respeitam os filtros selecionados.</p></div></div><div id="report-results"></div>`;let update=()=>{let fc=document.querySelector('#filter-class').value,fg=document.querySelector('#filter-game').value,fs=document.querySelector('#filter-status').value,list=attempts.filter(x=>(!fc||x.className===fc)&&(!fg||x.game===fg)&&(!fs||x.status===fs)),params=new URLSearchParams();if(fc)params.set('className',fc);if(fg)params.set('game',fg);if(fs)params.set('status',fs);let query=params.toString()?`?${params}`:'';document.querySelector('#teacher-report-pdf-link').href=`/api/teacher/report-pdf${query}`;document.querySelector('#teacher-report-print-link').href=`/api/teacher/report-print${query}`;let completed=list.filter(x=>x.status==='completed'),correct=completed.reduce((n,x)=>n+Number(x.correctAnswers),0),wrong=completed.reduce((n,x)=>n+Number(x.wrongAnswers),0);document.querySelector('#report-results').innerHTML=`<div class="report-summary"><div class="metric"><b>${new Set(list.map(x=>x.studentId)).size}</b> aluno(s)</div><div class="metric"><b>${list.length}</b> tentativa(s)</div><div class="metric"><b>${completed.length}</b> concluída(s)</div><div class="metric"><b>${correct+wrong?Math.round(correct/(correct+wrong)*100):0}%</b> acertos</div></div>${list.length?`<div class="reporttable-wrap"><table class="reporttable"><thead><tr><th>Aluno</th><th>Turma</th><th>Etapa</th><th>Jogo</th><th>Tentativa</th><th>Acertos</th><th>Erros</th><th>Situação</th><th>Data</th></tr></thead><tbody>${list.map(x=>{let errs=answers.filter(a=>a.attemptId===x.id&&!a.isCorrect);return `<tr><td>${escapeHtml(x.name)}</td><td>${escapeHtml(x.className)}</td><td>${escapeHtml(G[x.grade]?.name||x.grade)}</td><td>${escapeHtml(x.game)}</td><td>${x.attemptNumber}</td><td>${x.correctAnswers}/${x.totalQuestions}</td><td>${x.wrongAnswers}</td><td class="status-${x.status}">${x.status==='completed'?'Concluído':'Iniciado'}</td><td>${new Date(x.completedAt||x.startedAt).toLocaleDateString('pt-BR')}</td></tr>${errs.length?`<tr class="detailsrow"><td colspan="9"><b>Erros desta tentativa:</b><ul class="errorlist">${errs.map(a=>`<li>${escapeHtml(a.question)} — marcou “${escapeHtml(a.selectedAnswer)}”; correta: “${escapeHtml(a.correctAnswer)}”.</li>`).join('')}</ul></td></tr>`:''}`}).join('')}</tbody></table></div>`:'<div class="emptyreport">Nenhum resultado corresponde aos filtros.</div>'}`};document.querySelectorAll('.reportfilters select').forEach(x=>x.onchange=update);update()}
function teach(k){let map={6:{curriculo:'EF69LP07, EF69LP12, EF69LP55 e EF69LP56.',avaliacoes:'Rioeduca/SAEB: inferência, sentido contextual, variedades, oralidade, recursos de HQ e adequação.',objetivo:'Reconhecer que a língua muda e varia, localizar pistas verbais e visuais e diferenciar diversidade linguística de erro.',progressao:'No 6º ano, priorize observação, comparação e descoberta. Explore as imagens do manuscrito, o significado das palavras no contexto e exemplos próximos da realidade dos estudantes.'},9:{curriculo:'EF69LP55, EF69LP56, EF09LP07, EF89LP10 e EF89LP15.',avaliacoes:'SAEB/BNCC e Rioeduca/Trilhas: inferir, analisar recursos multissemióticos e variedades, identificar tese e avaliar argumentos.',objetivo:'Analisar argumentos sobre variação linguística e formular respostas fundamentadas contra estigmas e preconceitos.',progressao:'No 9º ano, avance da identificação para a argumentação. Compare posições, examine justificativas e peça que os estudantes refutem afirmações preconceituosas com evidências.'},3:{curriculo:'EM13LP10; variação, adequação, valores sociais e combate ao preconceito.',avaliacoes:'ENEM Linguagens, Competência 8: H25, H26 e H27.',objetivo:'Avaliar relações entre linguagem, identidade, prestígio e poder e interpretar criticamente discursos sobre usos da língua.',progressao:'No Ensino Médio, aprofunde a dimensão social e política. Relacione norma, prestígio e estigma, avalie teses e efeitos de sentido e discuta como o preconceito linguístico reforça desigualdades.'} }[k];return `<h2>Planejamento para o ${G[k].name}</h2><table><tr><th>Objetivo</th><td>${map.objetivo}</td></tr><tr><th>Currículo</th><td>${map.curriculo}</td></tr><tr><th>Avaliações</th><td>${map.avaliacoes}</td></tr></table><div class="note"><b>Progressão didática desta etapa</b><p>${map.progressao}</p></div><h2>Gabaritos</h2>${G[k].games.map(x=>`<div class="accordion"><button>${x} ＋</button><div><b>Objetivo:</b> ${desc(x)}<br><b>Respostas:</b> ${questionsFor(x,k).map((q,i)=>`${i+1}) ${q[1][q[2]]}`).join(' • ')}</div></div>`).join('')}`};
function institutional(){out(`<div class="pagehead"><h1>Identificação institucional</h1></div><section class="section cards"><div class="card"><span class="eyebrow">Projeto de iniciação científica</span><h2>Projeto</h2><p><b>wwwpelofimdopreconceitolinguístico.com.br: Linguística, Divulgação Científica e TICs</b></p><p><a class="btn institutionallink" href="https://sites.google.com/view/dastrevasparaaluz-uerj?usp=sharing" target="_blank" rel="noopener noreferrer">Acessar o site universitário ↗</a></p></div><div class="card"><span class="eyebrow">Produto educacional</span><h2>Da academia para a escola</h2><p>Este site realiza a transposição didática da pesquisa para a Educação Básica, com foco em mudança, variação e combate ao preconceito linguístico.</p></div><div class="card"><span class="eyebrow">Vinculação institucional</span><h2>UERJ</h2><p><b>Universidade do Estado do Rio de Janeiro</b><br>Centro de Educação e Humanidades<br>Instituto de Letras</p></div></section>`)};function contact(){out(`<div class="pagehead"><h1>Contato</h1></div><section class="section"><div class="card contactcard"><span class="eyebrow">E-mail oficial</span><h2>Entre em contato</h2><p>Envie dúvidas, sugestões ou solicitações para:</p><p><a class="contactmail" href="mailto:dastrevasparaaluz.uerj@gmail.com">dastrevasparaaluz.uerj@gmail.com</a></p></div></section>`)};
function participants(){let team=[{initials:'RL',name:'Ricardo Joseh Lima',role:'Coordenador do projeto',bio:'Professor titular de Linguística da Universidade do Estado do Rio de Janeiro.',period:'Coordenação do projeto de iniciação científica.',lattes:'http://lattes.cnpq.br/1072479286785521',email:'ricardo.lima@uerj.br'},{initials:'CD',name:'Caroline Meneses Domingos',role:'Pesquisadora de iniciação científica',bio:'Graduanda em Letras — Português/Literaturas de Língua Portuguesa.',period:'Bolsista PIBIC-UERJ de 2024 a 2026 e voluntária desde 2026.',lattes:'http://lattes.cnpq.br/0480413513647242',email:'carolinemeneses10@hotmail.com'},{initials:'MA',name:'Monique Massoni de Almeida',role:'Pesquisadora de iniciação científica',bio:'Graduanda em Letras — Português/Literaturas de Língua Portuguesa.',period:'Voluntária de 2024 a 2026 e bolsista PIBIC-UERJ desde 2026.',lattes:'http://lattes.cnpq.br/9035874258073302',email:'moniquealmeida018@gmail.com'},{initials:'RF',name:'Raquel Lara Ferreira',role:'Pesquisadora de iniciação científica',bio:'Graduanda em Letras — Português/Literaturas de Língua Portuguesa.',period:'Voluntária de iniciação científica desde 2024.',lattes:'http://lattes.cnpq.br/8856738094912271',email:'raq.lara13@gmail.com'}];out(`<div class="pagehead"><span class="eyebrow">Equipe do projeto</span><h1>Participantes</h1><p class="lead">Conheça as pessoas responsáveis pela pesquisa, pela construção do corpus e pela divulgação científica do projeto.</p></div><section class="section teamgrid">${team.map(p=>`<article class="card teamcard"><div class="avatar" aria-hidden="true">${p.initials}</div><span class="eyebrow">${p.role}</span><h2>${p.name}</h2><p>${p.bio}</p><p class="teampERIOD">${p.period}</p><div class="teamlinks"><a href="${p.lattes}" target="_blank" rel="noopener noreferrer">Currículo Lattes ↗</a><a href="mailto:${p.email}">${p.email}</a></div></article>`).join('')}</section>`)};
function aiUse(){out(`<div class="pagehead"><span class="eyebrow">Transparência e uso de IA</span><h1>Como a inteligência artificial foi utilizada?</h1><p class="lead">A inteligência artificial generativa foi empregada na programação, na elaboração das questões autorais e como ferramenta de apoio ao planejamento deste site. Seu uso ocorreu sob orientação, seleção e revisão humanas.</p></div><section class="section"><div class="aigrid"><article class="card"><span class="aiicon" aria-hidden="true">⌨️</span><h2>Desenvolvimento</h2><p>O ChatGPT, da OpenAI, realizou integralmente a programação do site, criando os códigos HTML, CSS e JavaScript, a estrutura do servidor, a navegação e os recursos de acessibilidade.</p></article><article class="card"><span class="aiicon" aria-hidden="true">🧭</span><h2>Questões e planejamento</h2><p>O ChatGPT elaborou integralmente as questões autorais a partir dos materiais didáticos e das referências indicados pela equipe, que orientou e revisou o conteúdo antes da publicação. A ferramenta também apoiou a organização das páginas e a adaptação da linguagem para as diferentes etapas escolares.</p></article><article class="card"><span class="aiicon" aria-hidden="true">🎨</span><h2>Recursos visuais</h2><p>A ilustração do dragão-guia Lume foi produzida com inteligência artificial generativa a partir das orientações e referências visuais fornecidas pela equipe.</p></article></div><div class="note humanreview"><h2>Supervisão humana</h2><p>As referências, informações científicas, escolhas pedagógicas, questões, textos e funcionalidades são selecionados, conferidos e revisados pela equipe do projeto antes da publicação. A inteligência artificial não substitui a autoria, a análise científica nem a responsabilidade humana.</p></div><div class="note ailimits"><h2>Limites do uso</h2><p>Ferramentas de IA podem produzir informações incompletas ou incorretas. Por isso, suas respostas são tratadas como material preliminar e confrontadas com as referências bibliográficas, os documentos curriculares e o corpus da pesquisa.</p></div></section>`)};
function sources(){out(`<div class="pagehead"><span class="eyebrow">Base documental do projeto</span><h1>Referências e créditos</h1><p class="lead">Referências organizadas conforme o modelo da ABNT. Os documentos curriculares, materiais didáticos, avaliações e fontes do corpus orientam a produção pedagógica do site.</p></div><section class="section references"><div class="note licensebox"><b>Direitos autorais e licença</b><p>Exceto quando indicado de outra forma, o conteúdo autoral deste site está licenciado sob a <a href="https://creativecommons.org/licenses/by/4.0/deed.pt-br" target="_blank" rel="license noopener noreferrer">Licença Creative Commons Atribuição 4.0 Internacional (CC BY 4.0)</a>.</p><p>A licença não se aplica a questões de avaliações, imagens, manuscritos, citações e demais materiais de terceiros, que permanecem sujeitos aos direitos e às condições indicados em suas respectivas fontes.</p></div><p class="note"><b>Nota editorial:</b> o banco reúne questões autorais integralmente elaboradas pelo ChatGPT a partir dos materiais didáticos e das referências selecionados pela equipe, que orientou e revisou o conteúdo, e questões selecionadas do Enem e do Vestibular Estadual da UERJ. As questões adaptadas dessas avaliações apresentam a instituição, o exame, o ano, a aplicação ou etapa, o caderno de questões e o número original do item. Quando houver alterações no enunciado, no texto-base ou nas alternativas, será identificada como “adaptada de”. Os demais materiais didáticos e curriculares são usados como referências de conteúdo e habilidades.</p>${REF_GROUPS.map(([title,items])=>`<section class="refgroup"><h2>${title}</h2><ol>${items.map(item=>`<li>${item}</li>`).join('')}</ol></section>`).join('')}</section>`)};
