function zoom(src,alt){modalOpener=document.activeElement;document.body.insertAdjacentHTML('beforeend',`<div class="modal" role="dialog" aria-modal="true" aria-label="${alt}"><div class="modalbox"><button class="close" aria-label="Fechar">×</button><img src="${src}" alt="${alt}"></div></div>`);let modal=document.querySelector('.modal');modal.onclick=e=>{if(e.target===modal||e.target.classList.contains('close'))closeModal()};modal.querySelector('.close').focus()};
